package com.pakrose.attendance;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
  DB db; LinearLayout root, list; EditText nameField, salaryField; TextView summary;
  String today(){ return new SimpleDateFormat("yyyy-MM-dd", Locale.US).format(new Date()); }
  int dp(int n){ return (int)(n*getResources().getDisplayMetrics().density); }
  public void onCreate(Bundle b){ super.onCreate(b); db=new DB(this); showHome(); }
  TextView text(String s,int size){ TextView t=new TextView(this); t.setText(s); t.setTextSize(size); t.setTextColor(0xff172033); t.setPadding(dp(8),dp(8),dp(8),dp(8)); return t; }
  Button button(String s,Runnable r){ Button b=new Button(this); b.setText(s); b.setOnClickListener(v->r.run()); return b; }
  void base(String title){ ScrollView sc=new ScrollView(this); root=new LinearLayout(this); root.setOrientation(1); root.setPadding(dp(16),dp(18),dp(16),dp(18)); root.setBackgroundColor(0xfff4f6fa); sc.addView(root); setContentView(sc); TextView h=text(title,23); h.setTypeface(null,Typeface.BOLD); h.setTextColor(0xff12345a); root.addView(h); }
  void showHome(){ base("Pak Rose Enterprises\nAttendance & Salary"); root.addView(text("Offline app • Data stays on this phone",14)); summary=text("Employees: "+db.count()+"     Date: "+today(),16); root.addView(summary); root.addView(button("+ Add Employee",()->addEmployee())); root.addView(button("Attendance Today",()->attendance())); root.addView(button("Monthly Salary Summary",()->payroll())); root.addView(button("Employee List",()->employees())); root.addView(button("Export CSV Backup",()->exportCsv())); root.addView(text("Important: Keep a regular CSV backup. Uninstalling the app or losing this phone may erase records.",13)); }
  void addEmployee(){ base("Add Employee"); nameField=new EditText(this); nameField.setHint("Employee full name"); root.addView(nameField); salaryField=new EditText(this); salaryField.setHint("Monthly salary (PKR)"); salaryField.setInputType(2); root.addView(salaryField); root.addView(button("Save Employee",()->{String n=nameField.getText().toString().trim(); String s=salaryField.getText().toString().trim(); if(n.isEmpty()||s.isEmpty()){msg("Name and salary are required");return;} db.add(n,Double.parseDouble(s)); msg("Employee saved"); showHome();})); root.addView(button("Back",()->showHome())); }
  void employees(){ base("Employees"); Cursor c=db.getEmployees(); while(c.moveToNext()){ final int id=c.getInt(0); root.addView(text(c.getString(1)+" — PKR "+(long)c.getDouble(2),17)); root.addView(button("Delete this employee",()->new AlertDialog.Builder(this).setMessage("Delete employee and attendance?").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{db.delete(id);employees();}).show())); } c.close(); root.addView(button("Back",()->showHome())); }
  void attendance(){ base("Attendance — "+today()); Cursor c=db.getEmployees(); if(!c.moveToFirst()){root.addView(text("Pehle employee add karein.",16));} else do { final int id=c.getInt(0); String n=c.getString(1); root.addView(text(n,18)); LinearLayout row=new LinearLayout(this); row.setOrientation(0); for(String st:new String[]{"P","A","PL","UL"}){ Button b=new Button(this); b.setText(st); b.setTextSize(12); b.setOnClickListener(v->{db.mark(id,today(),st); msg(n+": "+st+" saved");}); row.addView(b,new LinearLayout.LayoutParams(0,dp(52),1)); } root.addView(row); }while(c.moveToNext()); c.close(); root.addView(text("P = Present, A = Absent, PL = Paid Leave, UL = Unpaid Leave",13)); root.addView(button("Back",()->showHome())); }
  void payroll(){ base("Monthly Salary"); EditText month=new EditText(this); month.setHint("Month: YYYY-MM (e.g. 2026-11)"); month.setText(new SimpleDateFormat("yyyy-MM",Locale.US).format(new Date())); root.addView(month); TextView out=text("",16); root.addView(out); root.addView(button("Calculate",()->{String m=month.getText().toString().trim(); StringBuilder sb=new StringBuilder(); Cursor c=db.getEmployees(); while(c.moveToNext()){int id=c.getInt(0); String n=c.getString(1); double sal=c.getDouble(2); int days=daysIn(m); int unpaid=db.countStatus(id,m,"A")+db.countStatus(id,m,"UL"); double deduction=days>0?sal/days*unpaid:0; sb.append(n).append("\nBasic: PKR ").append((long)sal).append(" | Absent/Unpaid: ").append(unpaid).append(" | Est. payable: PKR ").append((long)(sal-deduction)).append("\n\n"); } c.close(); out.setText(sb.toString());})); root.addView(text("Calculation uses calendar days in selected month. Present and paid leave are paid; absent and unpaid leave are deducted per day. Advances and late/early penalties are not yet included in this starter build.",13)); root.addView(button("Back",()->showHome())); }
  int daysIn(String m){try{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM",Locale.US); Date d=f.parse(m); Calendar c=Calendar.getInstance();c.setTime(d);return c.getActualMaximum(Calendar.DAY_OF_MONTH);}catch(Exception e){return 0;}}
  void exportCsv(){ try{StringBuilder s=new StringBuilder("Employee,Monthly Salary\n");Cursor c=db.getEmployees();while(c.moveToNext())s.append('"').append(c.getString(1).replace("\"","\"\"")).append("\", ").append(c.getDouble(2)).append("\n");c.close();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"PakRose_Employees.csv");startActivityForResult(i,44); getPreferences(0).edit().putString("csv",s.toString()).apply();}catch(Exception e){msg("Export error");} }
  protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==44&&result==RESULT_OK&&data!=null){try{java.io.OutputStream o=getContentResolver().openOutputStream(data.getData());o.write(getPreferences(0).getString("csv","").getBytes("UTF-8"));o.close();msg("CSV backup saved");}catch(Exception e){msg("Could not save backup");}}}
  void msg(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
  class DB extends SQLiteOpenHelper { DB(Context c){super(c,"pakrose.db",null,1);} public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE employees(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,salary REAL)");d.execSQL("CREATE TABLE attendance(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id INTEGER,day TEXT,status TEXT,UNIQUE(employee_id,day))");} public void onUpgrade(SQLiteDatabase d,int a,int b){} void add(String n,double s){getWritableDatabase().execSQL("INSERT INTO employees(name,salary) VALUES(?,?)",new Object[]{n,s});} int count(){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM employees",null);c.moveToFirst();int x=c.getInt(0);c.close();return x;} Cursor getEmployees(){return getReadableDatabase().rawQuery("SELECT id,name,salary FROM employees ORDER BY name",null);} void delete(int id){getWritableDatabase().delete("employees","id=?",new String[]{""+id});getWritableDatabase().delete("attendance","employee_id=?",new String[]{""+id});} void mark(int id,String day,String st){getWritableDatabase().execSQL("INSERT OR REPLACE INTO attendance(employee_id,day,status) VALUES(?,?,?)",new Object[]{id,day,st});} int countStatus(int id,String m,String st){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM attendance WHERE employee_id=? AND day LIKE ? AND status=?",new String[]{""+id,m+"%",st});c.moveToFirst();int x=c.getInt(0);c.close();return x;} }
}
